macro_rules! CommitRef {
    () => {
        # [doc = " A git commit parsed using [`from_bytes()`](CommitRef::from_bytes())."] # [doc = ""] # [doc = " A commit encapsulates information about a point in time at which the state of the repository is recorded, usually after a"] # [doc = " change which is documented in the commit `message`."] # [derive (PartialEq , Eq , Debug , Hash , Ord , PartialOrd , Clone)] # [cfg_attr (feature = "serde" , derive (serde :: Serialize , serde :: Deserialize))] pub struct CommitRef < 'a > { # [doc = " HEX hash of tree object we point to. Usually 40 bytes long."] # [doc = ""] # [doc = " Use [`tree()`](CommitRef::tree()) to obtain a decoded version of it."] # [cfg_attr (feature = "serde" , serde (borrow))] pub tree : & 'a BStr , # [doc = " HEX hash of each parent commit. Empty for first commit in repository."] pub parents : SmallVec < & 'a BStr , 1 > , # [doc = " The raw author header value as encountered during parsing."] # [doc = ""] # [doc = " Use the [`author()`](CommitRef::author()) method to obtain a parsed version of it."] # [cfg_attr (feature = "serde" , serde (borrow))] pub author : & 'a BStr , # [doc = " The raw committer header value as encountered during parsing."] # [doc = ""] # [doc = " Use the [`committer()`](CommitRef::committer()) method to obtain a parsed version of it."] # [cfg_attr (feature = "serde" , serde (borrow))] pub committer : & 'a BStr , # [doc = " The name of the message encoding, otherwise [UTF-8 should be assumed](https://github.com/git/git/blob/e67fbf927dfdf13d0b21dc6ea15dc3c7ef448ea0/commit.c#L1493:L1493)."] pub encoding : Option < & 'a BStr > , # [doc = " The commit message documenting the change."] pub message : & 'a BStr , # [doc = " Extra header fields, in order of them being encountered, made accessible with the iterator returned by [`extra_headers()`](CommitRef::extra_headers())."] pub extra_headers : Vec < (& 'a BStr , Cow < 'a , BStr >) > , }
    };
}

CommitRef!();